/**
 * Props for BookingForm render prop component.
 * Supports two patterns:
 * 1. Client-side: Provide formId to load form dynamically
 * 2. SSR/SSG: Provide pre-loaded form object
 */
export type BookingFormProps = BookingFormWithFormIdProps | BookingFormWithFormProps;
/**
 * Core component that provides booking form data via render props.
 * Uses BookingFormService to manage form submission state.
 *
 * Supports two modes:
 * 1. Client-side: Provide formId to load the form dynamically
 * 2. SSR/SSG: Provide a pre-loaded form object
 *
 * This component:
 * - Sets up both FormService and BookingFormService in the same context
 * - BookingFormService internally accesses FormService for formValues
 * - Merges user's fieldMap with DEFAULT_BOOKING_FIELD_MAP
 * - Provides form data and actions via render props
 * - Form.* components (Form.Fields, Form.Loading, etc.) work because FormService is in context
 *
 * @component
 * @example
 * ```tsx
 * // Pattern 1: Client-side loading
 * import * as CoreBookingForm from '@wix/headless-bookings/react/core/booking-form';
 * import { Form } from '@wix/forms/components';
 *
 * <CoreBookingForm.Root formId="form-123">
 *   {({ formId, setFormSubmission, fields }) => (
 *     <Form.Fields
 *       fieldMap={fields}
 *       rowGapClassname="gap-y-4"
 *       columnGapClassname="gap-x-2"
 *     />
 *   )}
 * </CoreBookingForm.Root>
 * ```
 *
 * @example
 * ```tsx
 * // Pattern 2: SSR with pre-loaded form
 * import * as CoreBookingForm from '@wix/headless-bookings/react/core/booking-form';
 * import { loadBookingFormConfig } from '@wix/headless-bookings/services';
 *
 * // Server-side: Load form
 * const { form } = await loadBookingFormConfig('form-123');
 *
 * // Client-side: Render with pre-loaded form
 * <CoreBookingForm.Root form={form}>
 *   {({ formId, setFormSubmission, fields }) => (
 *     <Form.Fields fieldMap={fields} />
 *   )}
 * </CoreBookingForm.Root>
 * ```
 *
 * @example
 * ```tsx
 * // With custom field overrides and saving form values
 * <CoreBookingForm.Root
 *   formId="form-123"
 *   fieldMap={{ TEXT_INPUT: MyCustomTextInput }}
 * >
 *   {({ fields, formValues, setFormSubmission }) => (
 *     <>
 *       <Form.Fields fieldMap={fields} rowGapClassname="gap-y-4" columnGapClassname="gap-x-2" />
 *       <button onClick={() => setFormSubmission(formValues)}>
 *         Save
 *       </button>
 *     </>
 *   )}
 * </CoreBookingForm.Root>
 * ```
 */
export declare function Root(props: BookingFormProps): React.ReactNode;
/**
 * Props for BookingForm.LoadError component
 */
export interface LoadErrorProps {
    /** The error that was caught */
    error: Error;
    /** Whether to render as a child component */
    asChild?: boolean;
    /** Custom content to render. If not provided, displays the error message. */
    children?: React.ReactNode;
    /** Additional CSS class name */
    className?: string;
}
/**
 * Component to display when BookingForm fails to load due to configuration errors.
 * This component should be used in an error boundary to catch BookingFormConfigurationError.
 *
 * @component
 * @example
 * ```tsx
 * import * as CoreBookingForm from '@wix/headless-bookings/react/core/booking-form';
 *
 * // Default usage with className
 * <CoreBookingForm.LoadError error={error} className="text-destructive p-4" />
 *
 * // Custom content
 * <CoreBookingForm.LoadError error={error}>
 *   <div className="error-container">
 *     <h3>Error Loading Form</h3>
 *     <p>Please try again later.</p>
 *   </div>
 * </CoreBookingForm.LoadError>
 *
 * // With asChild for custom components
 * <CoreBookingForm.LoadError error={error} asChild>
 *   <CustomErrorComponent />
 * </CoreBookingForm.LoadError>
 * ```
 */
export declare const LoadError: React.ForwardRefExoticComponent<LoadErrorProps & React.RefAttributes<HTMLElement>>;
/**
 * Type guard to check if an error is a BookingFormConfigurationError
 */
export declare function isBookingFormConfigurationError(error: unknown): error is BookingFormConfigurationError;
export { BookingFormConfigurationError };
